-- Persist reconstruction end-state audits for list/detail status markers.
ALTER TABLE recons
  ADD COLUMN completion_status VARCHAR(10) NOT NULL DEFAULT 'unchecked'
  CHECK (completion_status IN ('solved', 'unsolved', 'invalid', 'unchecked'));

-- Snapshot audited against every row through #2572 on 2026-08-09. Rows created
-- after that snapshot stay unchecked until the API validates their next write.
UPDATE recons SET completion_status = 'solved' WHERE id <= 2572;

